"""Recover verified saved reviews, keep full-memory future picks, resume known pause."""
import argparse,base64,fcntl,hashlib,importlib.util,json,os,sys,tempfile,time
from pathlib import Path
FILES = {'manager_remembered_runtime.py': '', 'manager_practice_bridge.py': ''}
PREVIOUS = {'manager_remembered_runtime.py': '83749c27cdd036603af2dcd077872e6abe8328ea7e02cc62ce1b88fb6acd156e', 'manager_practice_bridge.py': '7f59847bec33b9d490252665b55b67d2e47ff1e278f68b61191e9e69536003cd'}

def sha(raw):return hashlib.sha256(raw).hexdigest()
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def atomic(p,raw):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.review-fix-')
    try:
        with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        os.replace(name,p)
    finally:
        if os.path.exists(name):os.unlink(name)

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--root',type=Path,default=Path('/home/ubuntu'));parser.add_argument('--apply',action='store_true');args=parser.parse_args()
    os.umask(0o077)
    root=args.root.resolve();state=root/'dj-manager-memory/runtime';active=read(state/'ACTIVATED.json')
    code=Path(active['code']).resolve();code.relative_to((root/'dj-manager-memory/runtime-code').resolve())
    payload={n:base64.b64decode(v) for n,v in FILES.items()};old={}
    for n,raw in payload.items():
        target=code/n;old[n]=target.read_bytes()
        if target.is_symlink() or (old[n]!=raw and sha(old[n])!=PREVIOUS[n]):
            raise ValueError('다른 실행 코드입니다. 변경 없음: '+n)
        compile(raw,str(target),'exec')
    if all(old[n]==raw for n,raw in payload.items()) and not (state/'PAUSED.json').exists():
        print('이미 적용·재개 준비 완료. 중복 AI 요청 없음');return
    with (state/'worker.lock').open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise SystemExit('기존 작업 실행 중. 변경·AI 요청 없음')
        pause=state/'PAUSED.json';pause_raw=pause.read_bytes()
        reason=json.loads(pause_raw).get('reason','')
        if not reason.startswith('구식으로 축소된 기억입니다.'):
            raise ValueError('예상과 다른 중단 사유. 재개 없음: '+reason)
        sys.path.insert(0,str(code))
        with tempfile.TemporaryDirectory(prefix='review-fix-check-') as tmp:
            for n,raw in payload.items():(Path(tmp)/n).write_bytes(raw)
            spec_bridge=importlib.util.spec_from_file_location('manager_practice_bridge',Path(tmp)/'manager_practice_bridge.py')
            bridge=importlib.util.module_from_spec(spec_bridge);spec_bridge.loader.exec_module(bridge)
            bridge.__file__=str(code/'manager_practice_bridge.py')
            sys.modules['manager_practice_bridge']=bridge
            p=Path(tmp)/'manager_remembered_runtime.py'
            spec=importlib.util.spec_from_file_location('manager_review_cache_check',p)
            rt=importlib.util.module_from_spec(spec);spec.loader.exec_module(rt)
            total=0;unstarted=0
            for engine in rt.ENGINES:
                for plan in sorted((state/'review_requests'/engine).glob('*/packets.json')):
                    if (plan.parent/'completed.json').exists():continue
                    for i,packet in enumerate(read(plan)):
                        if packet.get('analyst')!=engine or packet.get('mode')!='review':
                            raise ValueError('분석가 복기 연결 불일치')
                        response=rt.saved_historical_review(plan.parent,f'review-{i:03d}',packet)
                        if response is None and packet.get('memory',{}).get('retrieval_policy') not in (None,'preserved-paper-and-live-v2'):
                            if not rt.unstarted_review(plan.parent,f'review-{i:03d}'):
                                raise ValueError('이전 복기 요청이 시작된 흔적이 있습니다: '+str(plan))
                            unstarted+=1
                        total+=response is not None
        print(json.dumps({'check':'PASS','verified_saved_reviews':total,'unstarted_reviews':unstarted,'AI_requests':0,'files_changed':False},ensure_ascii=False),flush=True)
        if not args.apply:return
        if any((code/n).read_bytes()!=old[n] for n in payload) or pause.read_bytes()!=pause_raw or read(state/'ACTIVATED.json')!=active:
            raise ValueError('검증 중 상태 변경. 변경 없음')
        backup=state/'deployments'/('review-cache-recovery-'+str(time.time_ns()));backup.mkdir(parents=True)
        for n in payload:(backup/n).write_bytes(old[n])
        (backup/'PAUSED.before.json').write_bytes(pause_raw)
        try:
            for n,raw in payload.items():atomic(code/n,raw)
            if any((code/n).read_bytes()!=raw for n,raw in payload.items()):raise ValueError('적용 해시 불일치')
            pause.rename(backup/'PAUSED.resolved.json')
        except BaseException:
            for n,raw in old.items():atomic(code/n,raw)
            raise
        print('REVIEW_RECOVERY_INSTALLED · 기존 복기 답안·픽·기억 보존 · AI 요청 0회 · 재개 준비 완료')
        print('백업: '+str(backup))

if __name__=='__main__':main()
